<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login();
$number=trim($_GET['order']??'');$u=current_user();$row=null;$items=[];
if($db&&$number){$st=$db->prepare('SELECT o.*,u.full_name,u.email FROM orders o LEFT JOIN users u ON u.id=o.user_id WHERE o.order_number=? LIMIT 1');$st->execute([$number]);$row=$st->fetch();
 if($row && $u['role']!=='admin' && (int)$row['user_id']!==(int)$u['id']){http_response_code(403);exit('Forbidden');}
 if($row){$st=$db->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$st->execute([$row['id']]);$items=$st->fetchAll();}}
if(!$row){http_response_code(404);$title='Order Not Found';}else{$title='Order '. $row['order_number'];}
?><!doctype html><html lang="<?=e($LANG)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="simple-page"><div class="breadcrumbs">Home › Order Details</div><?php if(!$row):?><div class="empty"><h1>Order Not Found</h1><a class="btn primary" href="client.php">Back to Portal</a></div><?php else:?><div class="portal-welcome"><div><span class="eyebrow mint">ORDER DETAILS</span><h1><?=e($row['order_number'])?></h1><p><?=e($row['created_at'])?> · Status: <strong><?=e(ucfirst($row['status']))?></strong></p></div><a class="btn secondary" href="<?= $u['role']==='admin'?'admin-orders.php':'invoices.php' ?>">Back</a></div><section class="cart-card"><h2>Order Progress</h2><div class="dashboard-grid"><div class="dash-card"><span>Payment</span><strong><?=e(ucfirst($row['status']))?></strong></div><div class="dash-card"><span>Fulfillment</span><strong><?=e(ucwords(str_replace('_',' ',$row['fulfillment_status']??'pending'))) ?></strong></div></div><p class="muted">For VPS, Dedicated and other manually fulfilled services, payment confirmation is followed by provider purchase, configuration and service activation.</p></section><section class="cart-card"><h2>Items</h2><?php foreach($items as $it):?><div class="cart-row"><div><strong><?=e($it['description'])?></strong><small><?=e(ucfirst($it['item_type']))?> · <?=e($it['billing_cycle']??'')?></small></div><b><?=money($it['unit_price'],$it['currency'])?></b></div><?php endforeach;?><hr><div class="total">Total <strong><?=money($row['total'],$row['currency'])?></strong></div></section><?php endif;?></main><?php require __DIR__.'/includes/footer.php';?></body></html>
